begin;
select plan(9);
insert into auth.users (id, email) values ('aaaaaa25-0000-0000-0000-000000000001','u@x.test'),('aaaaaa25-0000-0000-0000-000000000007','admin@x.test');
insert into platform_roles (user_id, role) values ('aaaaaa25-0000-0000-0000-000000000007','admin');
insert into organizations (id, type, name) values ('cccccc25-0000-0000-0000-00000000000a','client_company','Org A'),('cccccc25-0000-0000-0000-00000000000b','individual','Org B');
insert into memberships (user_id, org_id, role) values ('aaaaaa25-0000-0000-0000-000000000001','cccccc25-0000-0000-0000-00000000000a','owner'),('aaaaaa25-0000-0000-0000-000000000001','cccccc25-0000-0000-0000-00000000000b','owner');
insert into projects (id, org_id, title, description, currency, status, visibility) values ('eeeeee25-0000-0000-0000-000000000001','cccccc25-0000-0000-0000-00000000000a','Project title','Detailed description','USD','open','public');
insert into proposals (id, project_id, org_id, cover_letter, price, currency, delivery_days, status) values ('ffffff25-0000-0000-0000-000000000001','eeeeee25-0000-0000-0000-000000000001','cccccc25-0000-0000-0000-00000000000b','Offer',10000,'USD',10,'shortlisted');
insert into provider_profiles (org_id, slug, headline) values ('cccccc25-0000-0000-0000-00000000000b','org-b-25','Org B headline');
update provider_profiles set verified_at = now() where org_id = 'cccccc25-0000-0000-0000-00000000000b';
update organizations set status = 'suspended' where id = 'cccccc25-0000-0000-0000-00000000000b';

set local role authenticated;
select set_config('request.jwt.claim.sub','aaaaaa25-0000-0000-0000-000000000001',true);
select throws_ok($$select create_contract('cccccc25-0000-0000-0000-00000000000a','ffffff25-0000-0000-0000-000000000001')$$, '42501', null, 'a person on both sides cannot hire their own suspended organization');
select is((select belongs_to('cccccc25-0000-0000-0000-00000000000b')), true, 'belongs_to ignores suspension');
select set_config('request.jwt.claim.sub','aaaaaa25-0000-0000-0000-000000000007',true);
select set_config('request.jwt.claims','{"aal":"aal2"}',true);
select throws_ok($$update platform_settings set value = '5000' where key = 'commission.client_bps'$$, '42501', null, 'an admin cannot write settings directly, even with aal2');
select throws_ok($$update plans set name = 'x' where key = 'free'$$, '42501', null, 'an admin cannot write plans directly');
select throws_ok($$update feature_flags set enabled = true where key = 'ai.assistant'$$, '42501', null, 'an admin cannot write flags directly');
select ok((select count(*) from platform_settings) > 0, 'an admin can still read settings');
reset role;
update organizations set status = 'active' where id = 'cccccc25-0000-0000-0000-00000000000b';
select is((select verified_at is not null from provider_profiles where org_id = 'cccccc25-0000-0000-0000-00000000000b'), true, 'verified before the rename');
update organizations set name = 'Renamed B' where id = 'cccccc25-0000-0000-0000-00000000000b';
select is((select verified_at is null from provider_profiles where org_id = 'cccccc25-0000-0000-0000-00000000000b'), true, 'renaming a verified organization removes the badge');
select is((select count(*)::int from audit_log where action = 'verification.cleared_on_rename'), 1, 'and records why');
select * from finish();
rollback;
